package eval

func worldEventsSuite() Suite {
	base := questRewardsSuite()
	return Suite{ID: "066-world-events", Name: "Campaign Play 066: World Events", Tests: append(base.Tests,
		playTest("play-world-events-turn-precondition", "Campaign turn is deterministic before world event scheduling", "GET", "/v1/play/campaigns/play-1/turn", nil, map[string]string{"Authorization": dmAuth}, 200, map[string]any{"turn_number": 3, "current_actor": "dm"}),
		playTest("play-world-event-player-forbidden", "Players cannot schedule world events", "POST", "/v1/play/campaigns/play-1/world-events", map[string]any{"event_id": "world-player", "turn_number": 4, "title": "Player Event", "text": "Players cannot write this."}, map[string]string{"Authorization": playerAAuth}, 403, nil),
		playTest("play-world-event-invalid-id", "World event scheduling requires a nonempty event ID", "POST", "/v1/play/campaigns/play-1/world-events", map[string]any{"event_id": "", "turn_number": 4, "title": "Storm Front", "text": "Black clouds gather over the cave road."}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-world-event-invalid-title", "World event scheduling requires a nonempty title", "POST", "/v1/play/campaigns/play-1/world-events", map[string]any{"event_id": "world-no-title", "turn_number": 4, "title": "", "text": "Black clouds gather over the cave road."}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-world-event-invalid-text", "World event scheduling requires nonempty text", "POST", "/v1/play/campaigns/play-1/world-events", map[string]any{"event_id": "world-no-text", "turn_number": 4, "title": "Storm Front", "text": ""}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-world-event-past-turn", "World events cannot be scheduled in a past turn", "POST", "/v1/play/campaigns/play-1/world-events", map[string]any{"event_id": "world-past", "turn_number": 2, "title": "Past Omen", "text": "This should not be accepted."}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTestExactJSON("play-world-event-schedule-future", "DM schedules a future world event", "POST", "/v1/play/campaigns/play-1/world-events", map[string]any{"event_id": "world-storm", "turn_number": 4, "title": "Storm Front", "text": "Black clouds gather over the cave road."}, map[string]string{"Authorization": dmAuth}, 201, map[string]any{"event_id": "world-storm", "turn_number": 4, "title": "Storm Front", "text": "Black clouds gather over the cave road.", "status": "scheduled"}),
		playTest("play-world-event-duplicate", "Duplicate world event IDs conflict", "POST", "/v1/play/campaigns/play-1/world-events", map[string]any{"event_id": "world-storm", "turn_number": 4, "title": "Storm Front", "text": "Black clouds gather over the cave road."}, map[string]string{"Authorization": dmAuth}, 409, nil),
		playTest("play-world-event-resolve-unknown", "Unknown world event resolution returns 404", "POST", "/v1/play/campaigns/play-1/world-events/world-missing/resolve", map[string]any{"text": "Nothing happens."}, map[string]string{"Authorization": dmAuth}, 404, nil),
		playTest("play-world-event-resolve-premature", "World events cannot resolve before their scheduled turn", "POST", "/v1/play/campaigns/play-1/world-events/world-storm/resolve", map[string]any{"text": "Rain floods the trail and slows any retreat."}, map[string]string{"Authorization": dmAuth}, 409, nil),
		playTest("play-world-event-advance-turn", "Existing DM resolution advances the campaign turn deterministically", "POST", "/v1/play/campaigns/play-1/resolutions", map[string]any{"text": "The party studies the cave mouth as thunder rolls in."}, map[string]string{"Authorization": dmAuth}, 201, map[string]any{"kind": "resolution", "actor": "dm", "next_actor": "player-a", "turn_number": 4}),
		playTestExactJSON("play-world-event-schedule-current", "DM can schedule a world event for the current turn", "POST", "/v1/play/campaigns/play-1/world-events", map[string]any{"event_id": "world-omen", "turn_number": 4, "title": "Ridge Omen", "text": "A horn echoes from the ridge."}, map[string]string{"Authorization": dmAuth}, 201, map[string]any{"event_id": "world-omen", "turn_number": 4, "title": "Ridge Omen", "text": "A horn echoes from the ridge.", "status": "scheduled"}),
		playTest("play-world-event-resolve-player-forbidden", "Players cannot resolve world events", "POST", "/v1/play/campaigns/play-1/world-events/world-storm/resolve", map[string]any{"text": "Rain floods the trail and slows any retreat."}, map[string]string{"Authorization": playerAAuth}, 403, nil),
		playTest("play-world-event-resolve-invalid-text", "World event resolution requires nonempty text", "POST", "/v1/play/campaigns/play-1/world-events/world-storm/resolve", map[string]any{"text": ""}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTestExactJSON("play-world-event-resolve", "DM resolves the scheduled world event at the matching turn", "POST", "/v1/play/campaigns/play-1/world-events/world-storm/resolve", map[string]any{"text": "Rain floods the trail and slows any retreat."}, map[string]string{"Authorization": dmAuth}, 201, map[string]any{"event_id": "world-storm", "turn_number": 4, "title": "Storm Front", "text": "Black clouds gather over the cave road.", "status": "resolved", "resolution": map[string]any{"turn_number": 4, "text": "Rain floods the trail and slows any retreat."}}),
		playTest("play-world-event-resolve-duplicate", "Duplicate world event resolution conflicts", "POST", "/v1/play/campaigns/play-1/world-events/world-storm/resolve", map[string]any{"text": "A changed resolution must not overwrite history."}, map[string]string{"Authorization": dmAuth}, 409, nil),
		playTestExactJSON("play-world-events-member-history", "Campaign members read exact ordered world event history", "GET", "/v1/play/campaigns/play-1/world-events", nil, map[string]string{"Authorization": playerBAuth}, 200, map[string]any{"events": []any{
			map[string]any{"event_id": "world-storm", "turn_number": 4, "title": "Storm Front", "text": "Black clouds gather over the cave road.", "status": "resolved", "resolution": map[string]any{"turn_number": 4, "text": "Rain floods the trail and slows any retreat."}},
			map[string]any{"event_id": "world-omen", "turn_number": 4, "title": "Ridge Omen", "text": "A horn echoes from the ridge.", "status": "scheduled"},
		}}),
	)}
}
